</head><body class="sb-admin-body"><div class="sb-page">
<div class="sb-topbar"><div><a class="sb-back-link" href="<?= htmlspecialchars($returnUrl,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8') ?>">← Назад</a><h1 class="sb-title">Состояние очереди</h1><p class="sb-subtitle"><?= $siteId>0?'Метрики сайта #'.$siteId:'Общие метрики transactional outbox' ?></p></div><div class="sb-actions"><a class="sb-btn sb-btn-light" href="<?= htmlspecialchars($basePath,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8') ?>/alerts.php<?= $siteId>0?'?siteId='.$siteId:'' ?>">Оповещения</a><a class="sb-btn sb-btn-light" href="<?= htmlspecialchars($basePath,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8') ?>/external_resources.php<?= $siteId>0?'?siteId='.$siteId:'' ?>">Внешние ресурсы</a><?php if($isBitrixAdmin):?><button class="sb-btn sb-btn-primary" id="runBtn">Запустить worker</button><?php endif;?><button class="sb-btn sb-btn-light" id="reloadBtn">Обновить</button></div></div>
