</div><script>(function(){'use strict';var BASE='<?= CUtil::JSEscape($basePath) ?>',SITE=<?= $siteId ?>,ADMIN=<?= $isBitrixAdmin?'true':'false' ?>,API=BASE+'/api.php';function sid(){return window.BX&&BX.bitrix_sessid?BX.bitrix_sessid():'<?= CUtil::JSEscape(bitrix_sessid()) ?>'}async function api(a,d){var r=await fetch(API,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:new URLSearchParams(Object.assign({action:a,sessid:sid()},d||{}))}),t=await r.text(),j;try{j=JSON.parse(t)}catch(e){throw{error:'BAD_JSON_RESPONSE'}}if(!j||j.ok!==true)throw j||{error:'UNKNOWN_ERROR'};return j}function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]})}function msg(t,e){var n=document.getElementById('message');n.style.display='block';n.style.color=e?'#991b1b':'#166534';n.textContent=t}async function load(){var r=await api('job.health',{siteId:SITE}),h=r.health||{},q=h.queue||{},o=h.operations||{};var st=document.getElementById('status');st.textContent=h.status||'unknown';st.className='health-status '+(h.status||'warning');document.getElementById('checkedAt').textContent=h.checkedAt||'';document.getElementById('ready').textContent=Number(q.ready||0);document.getElementById('running').textContent=Number(q.running||0);document.getElementById('dead').textContent=Number(q.dead||0);document.getElementById('oldest').textContent=Number(q.oldestReadySeconds||0)+' c';document.getElementById('criticalAlerts').textContent=Number(o.openCriticalAlerts||0);document.getElementById('resourceAnomalies').textContent=Number(o.externalAnomalies||0);document.getElementById('checks').innerHTML=(h.checks||[]).map(function(x){return '<div class="check '+esc(x.level||'')+'"><strong>'+esc(x.code||'')+'</strong> '+esc(x.seconds!=null?x.seconds+' c':x.count!=null?'('+x.count+')':'')+'</div>'}).join('')||'Проверок нет';document.getElementById('workers').innerHTML=(h.workers||[]).map(function(w){return '<tr><td>'+esc(w.workerId)+'</td><td>'+esc(w.status)+'</td><td>'+Number(w.heartbeatAgeSeconds||0)+' c назад</td><td>'+(w.currentJobId?'#'+Number(w.currentJobId):'—')+'</td><td>'+Number(w.succeededTotal||0)+'</td><td>'+Number(w.deadTotal||0)+'</td></tr>'}).join('')||'<tr><td colspan="6">Worker ещё не запускался</td></tr>';document.getElementById('daily').textContent=JSON.stringify(h.last24Hours||{},null,2)}document.getElementById('reloadBtn').onclick=function(){load().catch(function(e){msg(e.error||'Ошибка',true)})};if(ADMIN)document.getElementById('runBtn').onclick=function(){var b=this;b.disabled=true;api('job.run',{limit:20}).then(function(r){msg('Worker завершён: '+JSON.stringify(r.result||{}),false);return load()}).catch(function(e){msg(e.error||'Ошибка',true)}).finally(function(){b.disabled=false})};load().catch(function(e){msg(e.error||'Ошибка загрузки',true)});})();</script></body></html>
